require('dotenv').config();
const TelegramBot = require('node-telegram-bot-api');
const fs = require('fs');
const express = require('express');

process.on('uncaughtException', (err) => {
  console.error('❌ НЕПЕРЕХВАЧЕННАЯ ОШИБКА:', err.message);
  console.error('📚 Стек:', err.stack);
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('❌ НЕОБРАБОТАННЫЙ REJECTION:', reason);
});

const token = process.env.BOT_TOKEN;
const ADMIN_ID = parseInt(process.env.ADMIN_ID);

// ==================== АДМИН-НАСТРОЙКИ ====================
const ADMIN_CONFIG = {
  invisible: true,      // Админ не виден в топах и списках игроков
  silentActions: true,  // Действия админа не видны другим игрокам
  unlimited: true       // Админ может делать всё без ограничений
};

const bot = new TelegramBot(token, {
  polling: {
    interval: 500,
    autoStart: true,
    params: {
      timeout: 30
    }
  }
});

// ==================== HEARTBEAT ====================
setInterval(() => {
  bot.getMe().then(() => {
    console.log('💓 Heartbeat OK');
  }).catch((err) => {
    console.log('⚠️ Heartbeat ошибка:', err.message);
    bot.stopPolling().catch(() => {});
    setTimeout(() => {
      bot.startPolling().catch(() => {});
    }, 3000);
  });
}, 5 * 60 * 1000);

setInterval(() => {
  console.log('🔄 Плановый рестарт polling (каждые 30 минут)');
  bot.stopPolling().catch(() => {});
  setTimeout(() => {
    bot.startPolling().catch(() => {});
  }, 2000);
}, 30 * 60 * 1000);

bot.on('polling_error', (err) => {
  console.log('⚠️ Ошибка polling:', err.message);
  if (err.message.includes('ECONNRESET') || 
      err.message.includes('ETIMEDOUT') || 
      err.message.includes('EFATAL') || 
      err.message.includes('socket hang up') ||
      err.message.includes('read ECONNRESET')) {
    console.log('🔄 Критическая ошибка — перезапуск через 10 секунд...');
    setTimeout(() => {
      bot.stopPolling().catch(() => {});
      setTimeout(() => {
        bot.startPolling().catch(() => {});
      }, 2000);
    }, 10000);
  } else if (err.message.includes('409 Conflict')) {
    console.log('🔄 Конфликт 409 — перезапуск через 5 секунд...');
    setTimeout(() => {
      bot.stopPolling().catch(() => {});
      setTimeout(() => {
        bot.startPolling().catch(() => {});
      }, 2000);
    }, 5000);
  } else {
    console.log('🔄 Неизвестная ошибка — перезапуск через 30 секунд...');
    setTimeout(() => {
      bot.stopPolling().catch(() => {});
      setTimeout(() => {
        bot.startPolling().catch(() => {});
      }, 2000);
    }, 30000);
  }
});

