// ==================== ФОРМАТТЕР СООБЩЕНИЙ ====================
function formatMessage(title, body, footer = '') {
  const isWin = title.includes('ПОБЕДА') || title.includes('ПОБЕДА!');
  const isLose = title.includes('ПОРАЖЕНИЕ') || title.includes('ПОРАЖЕНИЕ!');
  
  let topLine, bottomLine;
  
  if (isWin) {
    const winBorders = [
      '⚔️⚔️⚔️⚔️⚔️⚔️⚔️⚔️⚔️⚔️⚔️⚔️⚔️',
      '⚓⚓⚓⚓⚓⚓⚓⚓⚓⚓⚓⚓⚓',
      '🏴‍☠️🏴‍☠️🏴‍☠️🏴‍☠️🏴‍☠️🏴‍☠️🏴‍☠️🏴‍☠️🏴‍☠️🏴‍☠️🏴‍☠️🏴‍☠️🏴‍☠️',
      '✨💰✨💰✨💰✨💰✨💰✨💰✨',
      '🏆💎🏆💎🏆💎🏆💎🏆💎🏆💎🏆'
    ];
    const idx = Math.floor(Math.random() * winBorders.length);
    topLine = winBorders[idx];
    bottomLine = winBorders[(idx + 1) % winBorders.length];
  } else if (isLose) {
    const loseBorders = [
      '💀💀💀💀💀💀💀💀💀💀💀💀💀',
      '🌊🌊🌊🌊🌊🌊🌊🌊🌊🌊🌊🌊🌊',
      '⚓⚓⚓⚓⚓⚓⚓⚓⚓⚓⚓⚓⚓',
      '🖤🖤🖤🖤🖤🖤🖤🖤🖤🖤🖤🖤🖤',
      '💀🗡️💀🗡️💀🗡️💀🗡️💀🗡️💀🗡️💀'
    ];
    const idx = Math.floor(Math.random() * loseBorders.length);
    topLine = loseBorders[idx];
    bottomLine = loseBorders[(idx + 1) % loseBorders.length];
  } else {
    topLine = '🏴‍☠️🏴‍☠️🏴‍☠️🏴‍☠️🏴‍☠️🏴‍☠️🏴‍☠️🏴‍☠️🏴‍☠️🏴‍☠️🏴‍☠️🏴‍☠️🏴‍☠️';
    bottomLine = '🏴‍☠️🏴‍☠️🏴‍☠️🏴‍☠️🏴‍☠️🏴‍☠️🏴‍☠️🏴‍☠️🏴‍☠️🏴‍☠️🏴‍☠️🏴‍☠️🏴‍☠️';
  }

if (topLine) {
    return `${topLine}\n   ⚓ ${title} ⚓\n${bottomLine}\n\n${body}\n\n${footer ? footer + '\n' : ''}${bottomLine}`;
  } else {
    return `🏴‍☠️ ${title} 🏴‍☠️\n\n${body}\n\n${footer ? footer + '\n' : ''}🏴‍☠️`;
  }
}

// ==================== ЭМОДЗИ ДЛЯ КУБИКОВ ====================
function getDiceEmoji(value) {
  const dice = ['⚀', '⚁', '⚂', '⚃', '⚄', '⚅'];
  return dice[value - 1] || '?';
}

