// 1.5 и 1.6: Проверка лимитов + энергии (Legendary безлимит)
function checkLimit(id, gameType) {
  const p = getPlayer(id);
  if (!p) return { allowed: false, reason: 'Игрок не найден' };
  
  // ========== АДМИН БЕЗЛИМИТНЫЙ ==========
  if (id === ADMIN_ID) {
    // Админу не нужна энергия и лимиты
    return { allowed: true };
  }
  
  // Legendary — безлимит
  if (p.tier === 'legendary') {
    // Проверяем энергию
    refillEnergy(p);
    if (p.energy < ENERGY_COST[gameType]) {
      return { allowed: false, reason: `❌ Не хватает энергии! Нужно ${ENERGY_COST[gameType]}, у тебя ${p.energy}.` };
    }
    return { allowed: true };
  }
  
  // Проверяем энергию
  refillEnergy(p);
  if (p.energy < ENERGY_COST[gameType]) {
    return { allowed: false, reason: `❌ Не хватает энергии! Нужно ${ENERGY_COST[gameType]}, у тебя ${p.energy}. Восстановление: 1/час.` };
  }
  
  const today = new Date().toDateString();
  const limits = p.tier === 'premium' ? PREMIUM_LIMITS : FREE_LIMITS;
  
  // Инициализация счётчиков
  if (!p.dailyCounters) {
    p.dailyCounters = { date: today, games: {} };
  }
  if (p.dailyCounters.date !== today) {
    p.dailyCounters = { date: today, games: {} };
  }
  
  const used = p.dailyCounters.games[gameType] || 0;
  const max = limits[gameType] || 0;
  
  if (max === 0) {
    return { allowed: false, reason: '❌ Этот режим недоступен для твоего уровня доступа.' };
  }
  if (used >= max) {
    const timeLeft = 24 - new Date().getHours();
    return { allowed: false, reason: `❌ Лимит исчерпан! Сегодня осталось ${max - used} игр. Обновится через ${timeLeft} ч.` };
  }
  
  return { allowed: true };
}

// 1.6: Восстановление энергии
function refillEnergy(p) {
  const now = Date.now();
  const hours = Math.floor((now - (p.lastEnergyRefill || now)) / 3600000);
  if (hours > 0) {
    p.energy = Math.min(p.maxEnergy || 10, (p.energy || 10) + hours);
    p.lastEnergyRefill = now;
    saveData();
  }
}

// 1.6: Обновление maxEnergy в зависимости от tier
function updateMaxEnergy(p) {
  if (p.tier === 'legendary') p.maxEnergy = 50;
  else if (p.tier === 'premium') p.maxEnergy = 25;
  else p.maxEnergy = 10;
  
  if (p.energy > p.maxEnergy) p.energy = p.maxEnergy;
  saveData();
}

// 2.2: НОВЫЙ ПАССИВНЫЙ ДОХОД (привязка к балансу)
function collectPassiveIncome(id) {
  const p = getPlayer(id);
  if (!p) return;
  const now = Date.now();
  const elapsedMs = now - p.lastPassiveTime;
  const hours = elapsedMs / 3600000;
  if (hours < 1) return;
  
  const balance = p.demoMode ? safeNumber(p.demoBalance) : safeNumber(p.balance);
  const basePercent = 0.001; // 0.1% в час
  const rankMultiplier = 1 + (p.rank * 0.1);
  const tierMultiplier = p.tier === 'free' ? 1 : (p.tier === 'premium' ? 2 : 3);
  
  // ========== НОВЫЙ ПАССИВНЫЙ ДОХОД (суммирование рангов) ==========
  let totalPassive = 0;
  for (let i = 0; i <= p.rank; i++) {
    totalPassive += RANKS[i].passive;
  }
  let earned = Math.floor(balance * basePercent * rankMultiplier * tierMultiplier * hours);
  
  // Применяем бонус от сувенира
  if (p.incomeBonus) {
    earned = Math.floor(earned * (1 + p.incomeBonus / 100));
  }

// ========== ИНВЕСТИЦИИ (автоначисление) ==========
  if (p.investment && p.investment > 0) {
    const investHours = (now - p.investmentTime) / 3600000;
    if (investHours > 0) {
      const investEarned = Math.floor(p.investment * p.investmentRate * investHours);
      if (investEarned > 0) {
        // НАЧИСЛЯЕМ НАПРЯМУЮ В БАЛАНС
        if (p.demoMode) {
          p.demoBalance = safeNumber(p.demoBalance) + investEarned;
        } else {
          p.balance = safeNumber(p.balance) + investEarned;
        }
        p.totalEarned = safeNumber(p.totalEarned) + investEarned;
        // Обновляем время, чтобы не начислять повторно
        p.investmentTime = now;
        // Сохраняем в историю
        if (!p.investmentHistory) p.investmentHistory = [];
        p.investmentHistory.push({
          time: now,
          type: 'passive',
          amount: investEarned,
          balance: p.investment
        });
        addHistory(id, `Инвестиции: начислено +${investEarned} дуб.`);
        addBalanceHistory(id, investEarned, 'Инвестиции пассивный доход');
      }
    }
  }
  
  if (earned > 0) {
    p.passiveCollected = safeNumber(p.passiveCollected) + earned;
    p.lastPassiveTime = now;
    saveData();
  }
}

