// ==================== ДУЭЛИ ====================
function processDuel(challengerId, opponentId, amount) {
  const challenger = getPlayer(challengerId);
  const opponent = getPlayer(opponentId);
  let round = 0;
  let winnerId = null;
  let roundResults = [];
  const challengerBet = amount;
  const opponentBet = amount;

  bot.sendSticker(challengerId, STICKERS.duel_player).catch(() => {});
  sleep(500);
  
  bot.sendMessage(challengerId, formatMessage('⚔️ VS ⚔️', ''));
  bot.sendMessage(opponentId, formatMessage('⚔️ VS ⚔️', ''));
  sleep(500);
  
  bot.sendSticker(opponentId, STICKERS.duel_opponent).catch(() => {});
  sleep(1500);
  
  while (round < 5 && !winnerId) {
    round++;
    const d1 = Math.floor(Math.random() * 6) + 1;
    const d2 = Math.floor(Math.random() * 6) + 1;
    const sum1 = d1 + d2;
    const d3 = Math.floor(Math.random() * 6) + 1;
    const d4 = Math.floor(Math.random() * 6) + 1;
    const sum2 = d3 + d4;
    bot.sendMessage(challengerId, formatMessage('ДУЭЛЬ РАУНД ' + round, `${d1}+${d2}=${sum1}`));
    bot.sendMessage(opponentId, formatMessage('ДУЭЛЬ РАУНД ' + round, `${d3}+${d4}=${sum2}`));
    roundResults.push({ round, challengerSum: sum1, opponentSum: sum2 });
    if (sum1 > sum2) {
      winnerId = challengerId;
    } else if (sum2 > sum1) {
      winnerId = opponentId;
    }
  }
  
  if (!winnerId) {
    if (challenger.demoMode) {
      challenger.demoBalance = safeNumber(challenger.demoBalance) + challengerBet;
    } else {
      challenger.balance = safeNumber(challenger.balance) + challengerBet;
    }
    if (opponent.demoMode) {
      opponent.demoBalance = safeNumber(opponent.demoBalance) + opponentBet;
    } else {
      opponent.balance = safeNumber(opponent.balance) + opponentBet;
    }
    bot.sendMessage(challengerId, formatMessage('ДУЭЛЬ', '🤝 Ничья после 5 раундов! Ставки возвращены.'));
    bot.sendMessage(opponentId, formatMessage('ДУЭЛЬ', '🤝 Ничья после 5 раундов! Ставки возвращены.'));
    saveData();
    return;
  }

const loserId = winnerId === challengerId ? opponentId : challengerId;
  const totalPot = amount * 2;
  const comm = Math.floor(totalPot * COMMISSION.duel);
  bank.commission = safeNumber(bank.commission) + comm;
  const winAmount = totalPot - comm;
  const winner = getPlayer(winnerId);
  
  if (winner.demoMode) {
    winner.demoBalance = safeNumber(winner.demoBalance) + winAmount;
  } else {
    winner.balance = safeNumber(winner.balance) + winAmount;
  }
  winner.duelStats.wins++;
  winner.duelStats.totalGames++;
  winner.totalEarned = safeNumber(winner.totalEarned) + winAmount;
  winner.games++;
  
  const loser = getPlayer(loserId);
  loser.duelStats.losses++;
  loser.duelStats.totalGames++;
  loser.games++;
  
  addHistory(winnerId, `Дуэль: победа +${winAmount} (${roundResults.length} раундов)`);
  addBalanceHistory(winnerId, winAmount, 'Дуэль победа');
  addHistory(loserId, `Дуэль: поражение -${amount} (${roundResults.length} раундов)`);
  addBalanceHistory(loserId, -amount, 'Дуэль поражение');
  checkAchievements(winnerId);
  
  let resultMsg = `⚔️ ДУЭЛЬ ЗАВЕРШЕНА!\n\n`;
  roundResults.forEach(r => {
    resultMsg += `Раунд ${r.round}: ${r.challengerSum} vs ${r.opponentSum}\n`;
  });
  resultMsg += `\n🏆 Победитель: @${winner.username || winnerId}`;
  resultMsg += `\n💰 Выигрыш: ${winAmount} дуб. (комиссия: ${comm} дуб.)`;
  
  bot.sendMessage(challengerId, formatMessage('ДУЭЛЬ ЗАВЕРШЕНА', resultMsg), { reply_markup: duelResultKeyboard() });
  bot.sendMessage(opponentId, formatMessage('ДУЭЛЬ ЗАВЕРШЕНА', resultMsg), { reply_markup: duelResultKeyboard() });
  
  const challengerResult = winnerId === challengerId ? 'win' : 'lose';
  const opponentResult = winnerId === opponentId ? 'win' : 'lose';
  updateDailyStats(challengerId, 'duel', challengerResult, amount);
  updateDailyStats(opponentId, 'duel', opponentResult, amount);
  
  saveData();
}

function createDuelChallenge(id, amount) {
  const p = getPlayer(id);
  if (!p) return false;
  if (duelChallenges[id]) return false;
  duelChallenges[id] = {
    amount: amount,
    timestamp: Date.now(),
    isRealMoney: false,
    challenger: id
  };
  if (!p.activeDuelChallenges) p.activeDuelChallenges = [];
  p.activeDuelChallenges.push({ from: id, amount: amount });
  saveData();
  return true;
}

function cancelDuelChallenge(id) {
  if (duelChallenges[id]) {
    delete duelChallenges[id];
    const p = getPlayer(id);
    if (p && p.activeDuelChallenges) {
      p.activeDuelChallenges = p.activeDuelChallenges.filter(c => c.from !== id);
    }
    saveData();
    return true;
  }
  return false;
}

function startRound() {
  if (bank.roundActive) return;
  bank.roundActive = true;
  bank.roundEnd = Date.now() + 600000;
  for (let id in players) {
    if (players[id].bet > 0) {
      if (players[id].demoMode) {
        players[id].demoBalance = safeNumber(players[id].demoBalance) + players[id].bet;
      } else {
        players[id].balance = safeNumber(players[id].balance) + players[id].bet;
      }
      players[id].bet = 0;
      players[id].canDouble = false;
      players[id].hasRolled = false;
      players[id].point = 0;
    }
    if (players[id].demoBet > 0) {
      players[id].demoBet = 0;
      players[id].demoCanDouble = false;
      players[id].demoHasRolled = false;
      players[id].demoPoint = 0;
    }
  }
  saveData();
  const now = Date.now();
  for (let id in players) {
    const p = players[id];
    const balance = p.demoMode ? safeNumber(p.demoBalance) : safeNumber(p.balance);
    if ((balance > 0 || safeNumber(p.demoBalance) > 0) && (now - p.lastPassiveTime < 86400000)) {
      bot.sendMessage(id, formatMessage('НОВЫЙ РАУНД', `Банк: ${safeNumber(bank.pot)} | Джекпот: ${safeNumber(bank.jackpot)}`)).catch(() => {});
    }
  }
  if (roundTimer) clearTimeout(roundTimer);
  roundTimer = setTimeout(() => {
    bank.roundActive = false;
    const jackpotPart = Math.floor(safeNumber(bank.pot) * 0.8);
    bank.jackpot = safeNumber(bank.jackpot) + jackpotPart;
    bank.pot = safeNumber(bank.pot) - jackpotPart;
    for (let id in players) {
      const p = players[id];
      const balance = p.demoMode ? safeNumber(p.demoBalance) : safeNumber(p.balance);
      if ((balance > 0 || safeNumber(p.demoBalance) > 0) && (Date.now() - p.lastPassiveTime < 86400000)) {
        bot.sendMessage(id, formatMessage('РАУНД ЗАВЕРШЁН', `${jackpotPart} ушло в джекпот (теперь ${safeNumber(bank.jackpot)})\nНовый раунд через 30 сек.`)).catch(() => {});
      }
    }
    saveData();
    setTimeout(() => { bank.roundActive = false; startRound(); }, 30000);
  }, 600000);
}

// 2.1: Распределение долей в банке
function distributeShares() {
  const totalShares = Object.values(players).reduce((sum, p) => sum + (p.share || 0), 0);
  if (totalShares === 0) return;
  
  const profit = Math.floor(safeNumber(bank.pot) * 0.01);
  if (profit === 0) return;
  
  for (let id in players) {
    const p = players[id];
    if (p.share > 0 && p.tier === 'legendary') {
      const income = Math.floor(profit * (p.share / totalShares));
      if (income > 0) {
        if (p.demoMode) {
          p.demoBalance = safeNumber(p.demoBalance) + income;
        } else {
          p.balance = safeNumber(p.balance) + income;
        }
        addHistory(id, `Доля в банке: +${income} дуб. (${p.share}%)`);
      }
    }
  }
  saveData();
}

function startTournament() {
  tournaments.active = true;
  tournaments.players = [];
  tournaments.prizePool = 0;
  tournaments.endTime = Date.now() + TOURNAMENT_CONFIG.duration;
  tournaments.results = [];
  saveData();
  for (let id in players) {
    bot.sendMessage(id, formatMessage(
      '⚔️ ТУРНИР НАЧАЛСЯ!',
      `💰 Вход: ${TOURNAMENT_CONFIG.entryFee} дуб.\n🏆 Призовой фонд: ${tournaments.prizePool} дуб.\n⏳ Длится: 7 дней\n\nУчаствуй! Нажми "✅ Участвовать"`
    )).catch(() => {});
  }
}

function endTournament() {
  if (!tournaments.active) return;
  tournaments.active = false;
  const sorted = tournaments.players.sort((a, b) => {
    const balA = players[a]?.balance || 0;
    const balB = players[b]?.balance || 0;
    return balB - balA;
  });
  tournaments.results = sorted;
  if (sorted.length > 0) {
    const winnerId = sorted[0];
    const prize = Math.floor(tournaments.prizePool * TOURNAMENT_CONFIG.winnerPercent);
    if (players[winnerId]) {
      if (players[winnerId].demoMode) {
        players[winnerId].demoBalance = safeNumber(players[winnerId].demoBalance) + prize;
      } else {
        players[winnerId].balance = safeNumber(players[winnerId].balance) + prize;
      }
      bot.sendMessage(winnerId, formatMessage('🏆 ПОБЕДА В ТУРНИРЕ!', `Ты получил ${prize} дуб.`));
    }
    if (sorted.length > 1) {
      const secondPrize = Math.floor(tournaments.prizePool * 0.2);
      const secondId = sorted[1];
      if (players[secondId]) {
        if (players[secondId].demoMode) {
          players[secondId].demoBalance = safeNumber(players[secondId].demoBalance) + secondPrize;
        } else {
          players[secondId].balance = safeNumber(players[secondId].balance) + secondPrize;
        }
        bot.sendMessage(secondId, formatMessage('🥈 2-е МЕСТО!', `Ты получил ${secondPrize} дуб.`));
      }
    }
    if (sorted.length > 2) {
      const thirdPrize = Math.floor(tournaments.prizePool * 0.1);
      const thirdId = sorted[2];
      if (players[thirdId]) {
        if (players[thirdId].demoMode) {
          players[thirdId].demoBalance = safeNumber(players[thirdId].demoBalance) +
            thirdPrize;
        } else {
          players[thirdId].balance = safeNumber(players[thirdId].balance) + thirdPrize;
        }
        bot.sendMessage(thirdId, formatMessage('🥉 3-е МЕСТО!', `Ты получил ${thirdPrize} дуб.`));
      }
    }
    const participationBonus = Math.floor(tournaments.prizePool * 0.02);
    for (let i = 3; i < Math.min(10, sorted.length); i++) {
      const pid = sorted[i];
      if (players[pid]) {
        if (players[pid].demoMode) {
          players[pid].demoBalance = safeNumber(players[pid].demoBalance) + participationBonus;
        } else {
          players[pid].balance = safeNumber(players[pid].balance) + participationBonus;
        }
        bot.sendMessage(pid, formatMessage('🎉 УЧАСТИЕ В ТУРНИРЕ!', `Ты получил ${participationBonus} дуб. за участие.`));
      }
    }
  }
  saveData();
  setTimeout(() => { startTournament(); }, 7 * 86400000);
}

function scheduleTournament() {
  const now = new Date();
  const day = now.getDay();
  const hours = now.getHours();
  const minutes = now.getMinutes();
  const seconds = now.getSeconds();
  const msUntilSunday = ((7 - day) % 7) * 86400000 + (23 - hours) * 3600000 + (59 - minutes) * 60000 + (59 - seconds) * 1000;
  setTimeout(() => {
    startTournament();
    setTimeout(() => {
      endTournament();
      scheduleTournament();
    }, TOURNAMENT_CONFIG.duration);
  }, msUntilSunday);
}

// ==================== ФУНКЦИЯ ОБНОВЛЕНИЯ СТАТИСТИКИ ====================
function updateDailyStats(id, gameType, result, betAmount) {
  const p = getPlayer(id);
  if (!p) return;
  
  const today = new Date().toDateString();
  
  if (p.gamesDate !== today) {
    p.gamesToday = 0;
    p.gamesDate = today;
  }
  if (p.winsDate !== today) {
    p.winsToday = 0;
    p.winsDate = today;
  }
  if (p.betDate !== today) {
    p.betToday = 0;
    p.betDate = today;
  }
  if (p.duelDate !== today) {
    p.duelToday = 0;
    p.duelDate = today;
  }
  if (p.blackjackWinsDate !== today) {
    p.blackjackWinsToday = 0;
    p.blackjackWinsDate = today;
  }
  if (p.chestsDate !== today) {
    p.chestsToday = 0;
    p.chestsDate = today;
  }
  
  p.games = (p.games || 0) + 1;
  p.gamesToday = (p.gamesToday || 0) + 1;
  
  if (betAmount) {
    p.betToday = (p.betToday || 0) + betAmount;
  }
  
  if (result === 'win') {
    p.wins = (p.wins || 0) + 1;
    p.winsToday = (p.winsToday || 0) + 1;
  } else if (result === 'lose') {
    p.losses = (p.losses || 0) + 1;
  }
  
  if (gameType === 'duel') {
    p.duelToday = (p.duelToday || 0) + 1;
  }
  
  if (gameType === 'blackjack' && result === 'win') {
    p.blackjackWinsToday = (p.blackjackWinsToday || 0) + 1;
  }
  
  // Шанс выпадения карты в играх (5%)
  if (Math.random() < 0.05) {
    const card = giveCardToUser(id);
    if (card) {
      const phrase = CARD_DROP_PHRASES[Math.floor(Math.random() * CARD_DROP_PHRASES.length)];
      bot.sendMessage(id, formatMessage(
        '🃏 НОВАЯ КАРТА!',
        `${phrase}\n\n${card.emoji} ${card.name}\n📊 Редкость: ${card.rarity}\n${card.bonus > 0 ? `📈 Бонус: +${card.bonus}%` : '🆕 Обычная карта'}`
      ));
    }
  }
  
  saveData();

  const quests = checkDailyQuests(id);
  if (quests) {
    for (let q of quests) {
      if (typeof q.condition === 'function' && q.condition(p) && !(p.dailyQuestsCompleted || []).includes(q.id)) {
        const success = completeDailyQuest(id, q.id);
        if (success) {
          bot.sendMessage(id, formatMessage('📋 ЗАДАНИЕ ВЫПОЛНЕНО!', `✅ ${q.name}\n💰 +${q.reward} дуб.`));
        }
      }
    }
  }
}

